class vm_stack
{
public:
  void pop(int);
  void* get_SP();
  bool push(char*, int);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    function(script_library_class*, const char*);
    virtual ~function();
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

struct vm_entity_list_iterator_t
{
  vm_entity_list_iterator_t& operator--();
};

struct entity_list
{
  vm_entity_list_iterator_t end();
};

typedef entity_list* vm_entity_list_t;

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( "script stack overflow" )
#define SLF_DONE return true

void error(const char*);

// script library function:  entity_list_iterator entity_list::rbegin()
class slf_entity_list_rbegin_t : public script_library_class::function
  {
  public:
    // constructor required
    slf_entity_list_rbegin_t(script_library_class* slc,const char* n) : script_library_class::function(slc,n) {}
    // library function parameters
    struct parms_t
      {
      // parameters
      vm_entity_list_t me;
      };
    // library function execution
    virtual bool operator()(vm_stack& stack,entry_t entry)
      {
      SLF_PARMS;
      vm_entity_list_iterator_t result = parms->me->end();
	    --result;
      SLF_RETURN;
      SLF_DONE;
      }
  };
